package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.util.*;
@Service @Transactional class InventoryService { private final InventoryLotRepository lots; private final StockMovementRepository movements; private final InventoryBalanceRepository balances; private final InventoryCommandRepository commands; private final IngredientRepository ingredients; private final SupplierRepository suppliers; private final LocationRepository locations; private final LotQuarantineRepository quarantines; private final AuditService audit;
 InventoryService(InventoryLotRepository l,StockMovementRepository m,InventoryBalanceRepository b,InventoryCommandRepository c,IngredientRepository i,SupplierRepository s,LocationRepository loc,LotQuarantineRepository q,AuditService a){lots=l;movements=m;balances=b;commands=c;ingredients=i;suppliers=s;locations=loc;quarantines=q;audit=a;}
 private void editor(Membership m){if(!(m.role==OrganizationRole.ORG_ADMIN||m.role==OrganizationRole.WAREHOUSE_MANAGER||m.role==OrganizationRole.FOOD_SAFETY_MANAGER))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Your role cannot change inventory.");}
 InventoryLotResponse receive(Membership m,ReceiveLotRequest r){return receive(m,r,null);} InventoryLotResponse transfer(Membership m,UUID lotId,TransferRequest r){return transfer(m,lotId,r,null);} InventoryLotResponse adjust(Membership m,UUID lotId,AdjustmentRequest r){return adjust(m,lotId,r,null);} InventoryLotResponse reduce(Membership m,UUID lotId,StockReductionRequest r,MovementType type){return reduce(m,lotId,r,type,null);}
 InventoryLot consumeForProduction(Membership m,UUID lotId,UUID locationId,BigDecimal quantity,String note){editor(m);var lot=lockedLot(m,lotId);notQuarantined(lot);location(m,locationId);requireAvailable(lot,locationId,quantity);apply(lot,locationId,quantity.negate());movements.save(new StockMovement(m.organizationId,lot.id,locationId,null,MovementType.PRODUCTION_CONSUMPTION,quantity,note));audit.record(m,"INVENTORY_CONSUMED_FOR_PRODUCTION","INVENTORY_LOT",lot.id,"Consumed "+quantity+" "+lot.unit);return lot;}
 InventoryLotResponse receive(Membership m,ReceiveLotRequest r,String key){editor(m);var repeated=repeated(m,key);if(repeated!=null)return repeated;var ingredient=ingredients.findByIdAndOrganizationId(r.ingredientId(),m.organizationId).orElseThrow(()->notFound("Ingredient"));var supplier=suppliers.findByIdAndOrganizationId(r.supplierId(),m.organizationId).orElseThrow(()->notFound("Supplier"));location(m,r.locationId());if(r.expiryDate()!=null&&r.manufactureDate()!=null&&r.expiryDate().isBefore(r.manufactureDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Expiry date cannot be before manufacture date.");var lot=lots.save(new InventoryLot(m.organizationId,ingredient.id,supplier.id,r.supplierBatchNumber().trim(),r.manufactureDate(),r.expiryDate(),r.unit().trim()));apply(lot,r.locationId(),r.quantity());movements.save(new StockMovement(m.organizationId,lot.id,null,r.locationId(),MovementType.RECEIPT,r.quantity(),blank(r.note())));complete(m,key,"RECEIPT",lot);audit.record(m,"INVENTORY_RECEIVED","INVENTORY_LOT",lot.id,"Received "+r.quantity()+" "+lot.unit);return inventoryLot(m,lot);}
 InventoryLotResponse transfer(Membership m,UUID lotId,TransferRequest r,String key){editor(m);var repeated=repeated(m,key);if(repeated!=null)return repeated;var lot=lockedLot(m,lotId);notQuarantined(lot);location(m,r.fromLocationId());location(m,r.toLocationId());if(r.fromLocationId().equals(r.toLocationId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Source and destination locations must be different.");requireAvailable(lot,r.fromLocationId(),r.quantity());apply(lot,r.fromLocationId(),r.quantity().negate());apply(lot,r.toLocationId(),r.quantity());movements.save(new StockMovement(m.organizationId,lot.id,r.fromLocationId(),r.toLocationId(),MovementType.TRANSFER,r.quantity(),blank(r.note())));complete(m,key,"TRANSFER",lot);audit.record(m,"INVENTORY_TRANSFERRED","INVENTORY_LOT",lot.id,"Transferred "+r.quantity()+" "+lot.unit);return inventoryLot(m,lot);}
 InventoryLotResponse adjust(Membership m,UUID lotId,AdjustmentRequest r,String key){editor(m);var repeated=repeated(m,key);if(repeated!=null)return repeated;var lot=lockedLot(m,lotId);notQuarantined(lot);location(m,r.locationId());if(r.quantity().signum()==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Adjustment quantity cannot be zero.");if(r.quantity().signum()<0)requireAvailable(lot,r.locationId(),r.quantity().abs());apply(lot,r.locationId(),r.quantity());UUID from=r.quantity().signum()<0?r.locationId():null;UUID to=r.quantity().signum()>0?r.locationId():null;movements.save(new StockMovement(m.organizationId,lot.id,from,to,MovementType.ADJUSTMENT,r.quantity().abs(),blank(r.note())));complete(m,key,"ADJUSTMENT",lot);audit.record(m,"INVENTORY_ADJUSTED","INVENTORY_LOT",lot.id,"Adjusted by "+r.quantity()+" "+lot.unit);return inventoryLot(m,lot);}
 InventoryLotResponse reduce(Membership m,UUID lotId,StockReductionRequest r,MovementType type,String key){editor(m);var repeated=repeated(m,key);if(repeated!=null)return repeated;var lot=lockedLot(m,lotId);notQuarantined(lot);location(m,r.locationId());requireAvailable(lot,r.locationId(),r.quantity());apply(lot,r.locationId(),r.quantity().negate());movements.save(new StockMovement(m.organizationId,lot.id,r.locationId(),null,type,r.quantity(),blank(r.note())));complete(m,key,type.name(),lot);audit.record(m,"INVENTORY_"+type.name(),"INVENTORY_LOT",lot.id,type+" "+r.quantity()+" "+lot.unit);return inventoryLot(m,lot);}
 List<InventoryLotResponse> inventory(Membership m){return lots.findByOrganizationIdOrderByReceivedAtDesc(m.organizationId).stream().map(x->inventoryLot(m,x)).toList();}
 TraceabilityResponse trace(Membership m,UUID lotId){var lot=lot(m,lotId);var move=movements.findByLotIdOrderByOccurredAt(lot.id);return new TraceabilityResponse(lotResponse(m,lot),move.stream().map(x->movementResponse(m,x)).toList(),balanceResponses(m,lot,move));}
 private InventoryLotResponse repeated(Membership m,String key){if(key==null||key.isBlank())return null;return commands.findByOrganizationIdAndActorIdAndIdempotencyKey(m.organizationId,m.userId,key.trim()).map(x->inventoryLot(m,lot(m,x.lotId))).orElse(null);}
 private void complete(Membership m,String key,String operation,InventoryLot lot){if(key!=null&&!key.isBlank())commands.save(new InventoryCommand(m.organizationId,m.userId,key.trim(),operation,lot.id));}
 private void apply(InventoryLot lot,UUID locationId,BigDecimal delta){var balance=balances.findByLotIdAndLocationId(lot.id,locationId).orElseGet(()->new InventoryBalance(lot.organizationId,lot.id,locationId,ledgerBalance(lot,locationId)));balance.add(delta);balances.save(balance);}
 private InventoryLotResponse inventoryLot(Membership m,InventoryLot lot){var all=movements.findByLotIdOrderByOccurredAt(lot.id);var balance=balanceResponses(m,lot,all);return new InventoryLotResponse(lotResponse(m,lot),balance,balance.stream().map(BalanceResponse::quantity).reduce(BigDecimal.ZERO,BigDecimal::add));}
 private List<BalanceResponse> balanceResponses(Membership m,InventoryLot lot,List<StockMovement> all){var names=locations.findByOrganizationIdOrderByName(m.organizationId).stream().collect(java.util.stream.Collectors.toMap(x->x.id,x->x.name));var persisted=balances.findByLotId(lot.id);if(!persisted.isEmpty())return persisted.stream().filter(x->x.quantity.compareTo(BigDecimal.ZERO)!=0).map(x->new BalanceResponse(x.locationId.toString(),names.getOrDefault(x.locationId,"Unknown location"),x.quantity,lot.unit)).toList();var values=new LinkedHashMap<UUID,BigDecimal>();for(var x:all){if(x.fromLocationId!=null)values.merge(x.fromLocationId,x.quantity.negate(),BigDecimal::add);if(x.toLocationId!=null)values.merge(x.toLocationId,x.quantity,BigDecimal::add);}return values.entrySet().stream().filter(e->e.getValue().compareTo(BigDecimal.ZERO)!=0).map(e->new BalanceResponse(e.getKey().toString(),names.getOrDefault(e.getKey(),"Unknown location"),e.getValue(),lot.unit)).toList();}
 private BigDecimal ledgerBalance(InventoryLot lot,UUID location){return movements.findByLotIdOrderByOccurredAt(lot.id).stream().map(x->{BigDecimal delta=BigDecimal.ZERO;if(location.equals(x.fromLocationId))delta=delta.subtract(x.quantity);if(location.equals(x.toLocationId))delta=delta.add(x.quantity);return delta;}).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private void notQuarantined(InventoryLot lot){if(quarantines.existsByLotIdAndActiveTrue(lot.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"This batch is quarantined and cannot be moved or used.");} private void requireAvailable(InventoryLot lot,UUID location,BigDecimal quantity){BigDecimal available=balances.findByLotIdAndLocationId(lot.id,location).map(x->x.quantity).orElseGet(()->ledgerBalance(lot,location));if(available.compareTo(quantity)<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock at the selected location.");}
 private InventoryLot lockedLot(Membership m,UUID id){return lots.findLockedByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->notFound("Batch"));} private InventoryLot lot(Membership m,UUID id){return lots.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->notFound("Batch"));}
 private Location location(Membership m,UUID id){return locations.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->notFound("Location"));}
 private LotResponse lotResponse(Membership m,InventoryLot x){var i=ingredients.findByIdAndOrganizationId(x.ingredientId,m.organizationId).orElseThrow();var s=suppliers.findByIdAndOrganizationId(x.supplierId,m.organizationId).orElseThrow();return new LotResponse(x.id.toString(),i.id.toString(),i.name,s.id.toString(),s.name,x.supplierBatchNumber,x.manufactureDate,x.expiryDate,x.unit,x.receivedAt);}
 private MovementResponse movementResponse(Membership m,StockMovement x){var from=x.fromLocationId==null?null:location(m,x.fromLocationId);var to=x.toLocationId==null?null:location(m,x.toLocationId);return new MovementResponse(x.id.toString(),x.movementType,x.fromLocationId==null?null:x.fromLocationId.toString(),from==null?null:from.name,x.toLocationId==null?null:x.toLocationId.toString(),to==null?null:to.name,x.quantity,x.note,x.occurredAt);}
 private ResponseStatusException notFound(String type){return new ResponseStatusException(HttpStatus.NOT_FOUND,type+" not found.");} private String blank(String x){return x==null||x.isBlank()?null:x.trim();}
}
